UPDATE courses SET
    course_description = '<html><body><div class="row-fluid"> <div class="span6 content"> <p style="font-weight:bold;"><span style="color: #000000;">You will learn to</span></p> <ul> <li>Effectively participate in a university or college course</li> <li>Express facts, ideas and opinions in writing, using correct and appropriate vocabulary, grammatical structures for academic purposes</li> <li>Understand spoken English in conversations, discussions and lectures and take notes</li> <li>Speak clearly and confidently in English</li> <li>Write well-structured and formatted texts of various types - such as essays - and understand academic texts</li> <li>Understand and deliver seminar presentations in English in front of a group</li> <li>Apply the skills and language studied to the IELTS examination.</li> </ul> <div class="hs-cta-node"> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_dnd_area-module-4_" style=""></span> </div> </div> <div class="span6 image"> </div> </div></body></html>',
