58d7e47852acc26b0b32fa98f4.1782479250262.1782479250262.1782479250262.1&amp;__hssc=122107220.6.1782479250262&amp;__hsfp=1921dd05a39ef67f80eb4e0098c0787f&amp;contentType=standard-page" id="cta_button_493380_08de26ea-8796-41b6-a4e0-7f9351d35137" style="" title="DOWNLOAD GUIDE">DOWNLOAD GUIDE</a></span><script charset="utf-8" src="/hs/cta/cta/current.js"></script><script type="text/javascript"> hbspt.cta._relativeUrls=true;hbspt.cta.load(493380, ''''c27d4c31-fe54-406f-aca3-fab27455ab6a'''', {"useNewLoader":"true","region":"na1"}); </script></span><!-- end HubSpot Call-to-Action Code --></span> </div> </div> </div> <div class="modal-footer"> <button class="close">X</button> </div> </div> </div> </div></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-2 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_dnd_area-module-2" style=""> <section class="heading-content" id="whyGreenwich"> <div class="container"> <div class="row"> <p style="font-weight:bold;">Master the English skills needed for academic success</p> <p style="text-align: center;">Nervous about the challenges associated with tertiary study in an English-speaking country? English for Academic Purposes (EAP) focuses on the presentation, essay writing and referencing skills you will need to survive and excel at university or college.</p> <p style="text-align: center;"> </p> </div> </div> </section></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-3 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_dnd_area-module-3" style=""> <section class="gwcMoreSupport"> <div class="container"> <div class="row-fluid"> <div class="span7 content"> <p style="font-weight:bold;">Who is this course for?</p> <p>EAP is designed for upper intermediate-level English students who want to improve their academic English skills in preparation for further study at University or College in an English-speaking country.</p> <p>EAP provides a pathway to many Colleges and Universities in Australia</p> <div class="hs-cta-node"> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_dnd_area-module-3_" style=""></span> </div> </div> <div class="span5 image"> </div> </div> </div> </section> <div class="testimonial-modal modal" id="testimonial_modal"> <div class="modal-dialog"> <!-- Modal content--> <div class="modal-content"> <div class="modal-body"> <div class="banner-video_pop"> </div> </div> <div class="modal-footer"> <button class="close">X</button> </div> </div> </div> </div></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-4 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_dnd_area-module-4" style=""> <section class="gwcMoreSupport"> <div class="container"> <div class="row-fluid"> <div class="span6 content"> <p style="font-weight:bold;"><span style="color: #000000;">You will learn to</span></p> <ul> <li>Effectively participate in a university or college course</li> <li>Express facts, ideas and opinions in writing, using correct and appropriate vocabulary, grammatical structures for academic purposes</li> <li>Understand spoken English in conversations, discussions and lectures and take notes</li> <li>Speak clearly and confidently in English</li> <li>Write well-structured and formatted texts of various types - such as essays - and understand academic texts</li> <li>Understand and deliver seminar presentations in English in front of a group</li> <li>Apply the skills and language studied to the IELTS examination.</li> </ul> <div class="hs-cta-node"> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_dnd_area-module-4_" style=""></span> </div> </div> <div class="span6 image"> </div> </div> </div> </section> <div class="testimonial-modal modal" id="testimonial_modal"> <div class="modal-dialog"> <!-- Modal content--> <div class="modal-content"> <div class="modal-body"> <div class="banner-video_pop"> </div> </div> <div class="modal-footer"> <button class="close">X</button> </div> </div> </div> </div></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-5 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-cell dnd-column" data-w="12" data-widget-type="cell" data-x="0" style=""> <div class="row-fluid-wrapper row-depth-1 row-number-6 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_widget_1682567051923" style=""> <section class="small-icon-module"> <div class="container"> <div class="small-icon-quick-info"> <div class="heading"> <p style="font-weight:bold;">You will learn this through</p> </div> <ul class="small-learn-icon"> <li> <a href=""> <p> Audio </p> </a> </li> <li> <a href=""> <p> DVD </p> </a> </li> <li> <a href=""> <p> Writing </p> </a> </li> <li> <a href=""> <p> Presentations </p> </a> </li> <li> <a href=""> <p> Lectures </p> </a> </li> <li> <a href=""> <p> Discussion </p> </a> </li> <li> <a href=""> <p> Case Studies </p> </a> </li> </ul> </div> </div> </section></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-7 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-cell dnd-column" data-w="12" data-widget-type="cell" data-x="0" style=""> <div class="row-fluid-wrapper row-depth-1 row-number-8 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_widget_1682568822168" style=""> <section class="span12 features-listnew"> <div class="span12 gwcFeatures"> <div class="row-fluid"> <div class="span12 gwcContainer"> <div class="row-fluid"> <div class="span12 sectionHead alignCenter heading"> <p style="font-weight:bold;">Why Study Academic English Preparation at Greenwich College?</p> </div> </div> <div class="row-fluid sectioncol"> <div class="span4 featureContentWrap2"> <div class="row-fluid"> <div class="span12 frnt2" style=''''background-image: url("https://www.greenwichcollege.edu.au/hs-fs/hubfs/05Hold_Images_New_Site/Courses/WhyGreenwichIMages/MoreOptionsFurtherStudy_360x430.jpg?width=360&amp;height=430&amp;name=MoreOptionsFurtherStudy_360x430.jpg");''''> <div class="row-fluid"> <div class="span12 frntImg"> </div> </div> <div class="row-fluid"> <div class="span12 frontCopy"> <p style="font-weight:bold;">More options for further study</p> <p> <a class="cta_button pinkCTAsmall" href="https://www.greenwichcollege.edu.au/english-courses/english-for-academic-purposes-eap?__hstc=122107220.53440f58d7e47852acc26b0b32fa98f4.1782479250262.1782479250262.1782479250262.1&amp;__hssc=122107220.6.1782479250262&amp;__hsfp=1921dd05a39ef67f80eb4e0098c0787f&amp;hsutk=53440f58d7e47852acc26b0b32fa98f4&amp;contentType=standard-page"> Read More </a> </p> </div> </div> </div> </div> <div class="row-fluid"> <div class="span12 bck2"> <div class="row-fluid"> <div class="span12 sectionCopy hover_section_part"> <div class="alignCenter"> <span class="hover-icon"></span> </div> <ul> <li> <p>This course offers a pathway to a range of Diploma programs offered at over 30 leading Australian universities and colleges – no need to complete IELTS.</p> </li> </ul> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1682568822168_" style=""></span> </div> </div> </div> </div> </div> <div class="span4 featureContentWrap2"> <div class="row-fluid"> <div class="span12 frnt2" style=''''background-image: url("https://www.greenwichcollege.edu.au/hs-fs/hubfs/05Hold_Images_New_Site/A-IMAGES/Misc-Images2/FreeTestPractice_AcademicSupport_545x430_1.jpg?width=545&amp;height=430&amp;name=FreeTestPractice_AcademicSupport_545x430_1.jpg");''''> <div class="row-fluid"> <div class="span12 frntImg"> </div> </div> <div class="row-fluid"> <div class="span12 frontCopy"> <p style="font-weight:bold;">Free Test Practice &amp; Academic Support</p> <p> <a class="cta_button pinkCTAsmall" href="https://www.greenwichcollege.edu.au/english-courses/english-for-academic-purposes-eap?__hstc=122107220.53440f58d7e47852acc26b0b32fa98f4.1782479250262.1782479250262.1782479250262.1&amp;__hssc=122107220.6.1782479250262&amp;__hsfp=1921dd05a39ef67f80eb4e0098c0787f&amp;hsutk=53440f58d7e47852acc26b0b32fa98f4&amp;contentType=standard-page"> Read More </a> </p> </div> </div> </div> </div> <div class="row-fluid"> <div class="span12 bck2"> <div class="row-fluid"> <div class="span12 sectionCopy hover_section_part"> <div class="alignCenter"> <span class="hover-icon"></span> </div> <ul> <li> <p>Achieve greater success with FREE test practice and personalised support including: - 5 extra hours of FREE test practice, presentations and tutorials to reinforce learning and monitor progress- Fortnightly one-on-one academic counselling, so you know where to focus your efforts.</p> </li> </ul> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1682568822168_" style=""></span> </div> </div> </div> </div> </div> <div class="span4 featureContentWrap2"> <div class="row-fluid"> <div class="span12 frnt2" style=''''background-image: url("https://www.greenwichcollege.edu.au/hs-fs/hubfs/05Hold_Images_New_Site/Courses/WhyGreenwichIMages/MoreFlexibility_360x430.jpg?width=360&amp;height=430&amp;name=MoreFlexibility_360x430.jpg");''''> <div class="row-fluid"> <div class="span12 frntImg"> </div> </div> <div class="row-fluid"> <div class="span12 frontCopy"> <p style="font-weight:bold;">Flexible Timetable options</p> <p> <a class="cta_button pinkCTAsmall" href="https://www.greenwichcollege.edu.au/english-courses/english-for-academic-purposes-eap?__hstc=122107220.53440f58d7e47852acc26b0b32fa98f4.1782479250262.1782479250262.1782479250262.1&amp;__hssc=122107220.6.1782479250262&amp;__hsfp=1921dd05a39ef67f80eb4e0098c0787f&amp;hsutk=53440f58d7e47852acc26b0b32fa98f4&amp;contentType=standard-page"> Read More </a> </p> </div> </div> </div> </div> <div class="row-fluid"> <div class="span12 bck2"> <div class="row-fluid"> <div class="span12 sectionCopy hover_section_part"> <div class="alignCenter"> <span class="hover-icon"></span> </div> <ul> <li> <p>Choose from morning or evening classes - so you can work and experience the best of Sydney and Melbourne while you study.</p> </li> </ul> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1682568822168_" style=""></span> </div> </div> </div> </div> </div> </div> </div> </div> </div> </section></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-9 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_dnd_area-module-6" style=""> <section class="span12 features-listnew"> <div class="span12 gwcFeatures"> <div class="row-fluid"> <div class="span12 gwcContainer"> <div class="row-fluid sectioncol"> </div> </div> </div> </div> </section></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-10 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-cell dnd-column" data-w="12" data-widget-type="cell" data-x="0" style=""> <div class="row-fluid-wrapper row-depth-1 row-number-11 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_widget_1682570551507" style=""> <div class="table-section"> <div class="container"> <p class="table-section__heading" style="font-weight:bold;">Sample Timetable</p> <div class="link-ribbon"> <ul> <li><a class="links tab-a active-a" data-id="day" href="javascript:void(0);">Day</a></li> <li><a class="links tab-a" data-id="night" href="javascript:void(0);">Night</a></li> </ul> </div> <div class="table-box tab tab-active" data-id="day" id="tableBox"> <div class="table-box__link link-ribbon"> <span class="link-title">Highlight:</span> <a class="links none-bg act-col" href="javascript:void(0);" id="none">None</a> <a class="links coure-units" href="javascript:void(0);" id="coure-units">Core Units</a> <a class="links optional-electives" href="javascript:void(0);" id="Optional">Optional Electives</a> </div> <table class="table table-block"> <tbody><tr class="table__tr table-heading-tr"> <th class="table__tdumn table-heading">Time</th> <th class="table__tdumn table-heading">Monday</th> <th class="table__tdumn table-heading">Tuesday</th> <th class="table__tdumn table-heading">Wednesday</th> <th class="table__tdumn table-heading">Thursday</th> <th class="table__tdumn table-heading">Friday</th> </tr> <tr class="table__tr"> <td class="table__tdumn table-data">09:00-10:30 </td> <td class="table__tdumn table-data cU"><strong>Last Week Review</strong></td> <td class="table__tdumn table-data cU"><strong>Grammar for <br/>Academic Purposes</strong><br/>Describing graphs<br/>and charts </td> <td class="table__tdumn table-data cU"><strong>Academic Reading Skills<br/></strong><br/>How can grammar help<br/> your reading?</td> <td class="table__tdumn table-data cU"><strong>Grammar for <br/>Academic Purposes</strong><br/>Using complex grammar<br/>structures in your<br/> writing</td> <td class="table__tdumn table-data oE" rowspan=""><strong>Practice Test<br/></strong><br/>Writing and Reading</td> </tr> <tr class="table__tr"> <td class="table__tdumn table-data">10:40-12:30 </td> <td class="table__tdumn table-data cU"><strong>Academic <br/>Vocabulary</strong><br/>Learning academic<br/>vocabulary related to the<br/>topic of the week</td> <td class="table__tdumn table-data cU"><strong>Listening to <br/>University Lectures<br/></strong><br/>Listening for important<br/> points and information</td> <td class="table__tdumn table-data cU"><strong>Vocabulary Builder<br/></strong><br/>Phrases and expressions connected to the <br/>topic of the week</td> <td class="table__tdumn table-data cU"><strong>Academic<br/>Vocabulary Revision</strong><br/>Reinforcing new vocabulary</td> <td class="table__tdumn table-data oE" rowspan=""><strong>Practice Test<br/></strong><br/>Listening and Speaking</td> </tr> <tr class="table__tr"> <td class="table__tdumn table-data">13:15-13:55 </td> <td class="table__tdumn table-data cU"><strong>Writing Skills<br/></strong><br/>The difference between <br/>formal and informal <br/>writing</td> <td class="table__tdumn table-data cU"><strong>Writing Skills<br/></strong><br/>How to write an essay</td> <td class="table__tdumn table-data cU"><strong>Writing Skills<br/></strong><br/>In class practice</td> <td class="table__tdumn table-data cU"><strong>Writing Skills<br/></strong><br/>Talking about <br/>complicated ideas</td> <td class="table__tdumn table-data oE" rowspan=""><strong>Individual Presentations</strong></td> </tr> <tr class="table__tr"> <td class="table__tdumn table-data">14:05-15:00</td> <td class="table__tdumn table-data cU"><strong>Academic Reading Techniques</strong><br/>Using special reading techniques to quickly find answers</td> <td class="table__tdumn table-data cU"><strong>Speaking</strong><br/>Debating techniques<br/>and practice </td> <td class="table__tdumn table-data cU"><strong>Academic Writing</strong><br/>How to do an academic <br/>presentation </td> <td class="table__tdumn table-data cU"><strong>Academic Writing<br/> Skills </strong><br/>Different types of<br/>essays </td> <td class="table__tdumn table-data oE" rowspan=""><strong>Feedback on <br/>Presentations</strong></td> </tr> </tbody></table> </div> <div class="table-box tab" data-id="night" id="tableBox"> <div class="table-box__link link-ribbon"> <span class="link-title">Highlight: </span> <a class="links none-bg act-col" href="javascript:void(0);" id="none">None</a> <a class="links coure-units" href="javascript:void(0);" id="coure-units">Core Units</a> <a class="links optional-electives" href="javascript:void(0);" id="Optional">Optional Electives</a> </div> <table class="table table-block"> <tbody><tr class="table__tr table-heading-tr"> <th class="table__tdumn table-heading">time</th> <th class="table__tdumn table-heading">monday</th> <th class="table__tdumn table-heading">tuesday</th> <th class="table__tdumn table-heading">wednesday</th> <th class="table__tdumn table-heading">thursday</th> <th class="table__tdumn table-heading">friday</th> </tr> </tbody></table> </div> </div> </div></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-12 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-cell dnd-column" data-w="12" data-widget-type="cell" data-x="0" style=""> <div class="row-fluid-wrapper row-depth-1 row-number-13 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_widget_1682571775912" style=""> <section class="span12 alignCenter sectionPadding needtoknow"> <div class="row-fluid"> <div class="span12 gwcContainer"> <div class="row-fluid"> <div class="span12 sectionHead needhead"> <p style="font-weight:bold;">Here''''s what you need to know</p> </div> </div> <div class="row-fluid"> <div class="span4 gwcNeedtoKnowThumb column"> <div class="row-fluid"> <div class="span12"> </div> </div> <div class="content"> <div class="row-fluid"> <div class="span12"> <p><strong>Entry Requirements</strong><br/>IELTS 6.0 or equivalent; or<br/>Greenwich English College Entry Test; or <br/>Offshore Entry Test available through a registered representatives.</p> </div> </div> </div> </div> <div class="span4 gwcNeedtoKnowThumb column"> <div class="row-fluid"> <div class="span12"> </div> </div> <div class="content"> <div class="row-fluid"> <div class="span12"> <p><strong>Course Commencement</strong><br/>Classes commence every 12 weeks.</p> </div> </div> </div> </div> <div class="span4 gwcNeedtoKnowThumb column"> <div class="row-fluid"> <div class="span12"> </div> </div> <div class="content"> <div class="row-fluid"> <div class="span12"> <p><strong>Course Duration</strong><br/>Classes are 12 weeks.</p> </div> </div> </div> </div> </div> </div> </div> </section></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div> </div> </div> </main> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_module_17616307527712" style=""><div class="footer-wrapper"> <div class="footer-grid"> <!-- Column 1: Logo and Social --> <div class="footer-column footer-logo-social" id="footer-logo"> <p class="footer-h2" style="font-weight:bold;">Stay Connected</p> <div class="social-icons-footer"> <a href="https://www.instagram.com/greenwichcollege/" rel="noopener noreferrer" target="_blank"><i class="fab fa-instagram"></i></a> <a href="https://www.facebook.com/GreenwichCollege/" rel="noopener noreferrer" target="_blank"><i class="fab fa-facebook-f"></i></a> <a href="https://www.linkedin.com/school/greenwich-college/" rel="noopener noreferrer" target="_blank"><i class="fab fa-linkedin-in"></i></a> <a href="https://www.youtube.com/channel/UCcatEHZzcyXn6k