UPDATE courses SET
    course_description = '<html><body><div class="row-fluid"> <div class="span6 content"> <p style="font-weight:bold;">Who is this course for?</p> <p>The Certificate IV in Leadership and Management is designed for students who want to build the skills and expertise to pursue leadership and management roles in business in an English-speaking country.</p> <p>This course helps students to develop skills across a range of areas including: customer service, financial administration and business communication to achieve success in a leadership position. Through our expert trainers and real-life case study approach, our graduates are job-ready faster.</p> <div class="hs-cta-node"> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_module_1720055451542_" style=""></span> </div> </div> <div class="span6 image"> </div> </div></body></html>',
    total_course_duration = '40-44 weeks',
