107220.9.1782479250262&amp;__hsfp=1921dd05a39ef67f80eb4e0098c0787f&amp;contentType=standard-page" id="cta_button_493380_08de26ea-8796-41b6-a4e0-7f9351d35137" style="" title="DOWNLOAD GUIDE">DOWNLOAD GUIDE</a></span><script charset="utf-8" src="/hs/cta/cta/current.js"></script><script type="text/javascript"> hbspt.cta._relativeUrls=true;hbspt.cta.load(493380, ''''c27d4c31-fe54-406f-aca3-fab27455ab6a'''', {"useNewLoader":"true","region":"na1"}); </script></span><!-- end HubSpot Call-to-Action Code --></span> </div> </div> </div> <div class="modal-footer"> <button class="close">X</button> </div> </div> </div> </div></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-2 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-cell dnd-column" data-w="12" data-widget-type="cell" data-x="0" style=""> <div class="row-fluid-wrapper row-depth-1 row-number-3 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_dnd_area-module-2" style=""> <section class="heading-content" id="whyGreenwich"> <div class="container"> <div class="row"> <p style="font-weight:bold;"> </p> <p style="font-weight:bold;">Build your business leadership skills</p> <p>This course introduces students to high-level skills such as marketing, innovation, team leadership and development to help them achieve success in a leadership position.</p> <p> </p> </div> </div> </section></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-4 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_module_1720055451542" style=""> <section class="gwcMoreSupport"> <div class="container"> <div class="row-fluid"> <div class="span6 content"> <p style="font-weight:bold;">Who is this course for?</p> <p>The Certificate IV in Leadership and Management is designed for students who want to build the skills and expertise to pursue leadership and management roles in business in an English-speaking country.</p> <p>This course helps students to develop skills across a range of areas including: customer service, financial administration and business communication to achieve success in a leadership position. Through our expert trainers and real-life case study approach, our graduates are job-ready faster.</p> <div class="hs-cta-node"> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_module_1720055451542_" style=""></span> </div> </div> <div class="span6 image"> </div> </div> </div> </section> <div class="testimonial-modal modal" id="testimonial_modal"> <div class="modal-dialog"> <!-- Modal content--> <div class="modal-content"> <div class="modal-body"> <div class="banner-video_pop"> </div> </div> <div class="modal-footer"> <button class="close">X</button> </div> </div> </div> </div></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-5 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_widget_1686638711612" style=""> <section class="gwcMoreSupport"> <div class="container"> <div class="row-fluid"> <div class="span6 content"> <p style="font-weight:bold;"><span style="color: #33475b;">You will learn to</span></p> <p><strong>BSBLDR411</strong> - Demonstrate leadership in the workplace (Core)<br/><strong>BSBLDR413</strong> - Lead effective workplace relationships (Core)<br/><strong>BSBOPS402</strong> - Coordinate business operational plans (Core)<br/><strong>BSBXCM401 </strong>- Apply communication strategies in the workplace (Core)<br/><strong>BSBXTW401</strong> - Lead and facilitate a team (Core)<br/><strong>BSBLDR412</strong> - Communicate effectively as a workplace leader<br/><strong>BSBLDR414</strong> - Lead team effectiveness<br/><strong>BSBPEF402 </strong>- Develop personal work priorities<br/><strong>BSBWHS411</strong> - Implement and monitor WHS policies, procedures and programs<br/><strong>BSBCRT412</strong> - Articulate, present and debate ideas<br/><strong>BSBOPS404</strong> - Implement customer service strategies<br/><strong>BSBPMG430</strong> - Undertake project work<br/><br/><strong>Career Opportunities:</strong><br/>Sales Manager, Operational Coordinator, and Team Leader. </p> <div class="hs-cta-node"> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1686638711612_" style=""></span> </div> </div> <div class="span6 image"> </div> </div> </div> </section> <div class="testimonial-modal modal" id="testimonial_modal"> <div class="modal-dialog"> <!-- Modal content--> <div class="modal-content"> <div class="modal-body"> <div class="banner-video_pop"> </div> </div> <div class="modal-footer"> <button class="close">X</button> </div> </div> </div> </div></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-6 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-cell dnd-column" data-w="12" data-widget-type="cell" data-x="0" style=""> <div class="row-fluid-wrapper row-depth-1 row-number-7 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_widget_1680146477177" style=""> <section class="small-icon-module"> <div class="container"> <div class="small-icon-quick-info"> <div class="heading"> <p style="font-weight:bold;">You will learn this through</p> </div> <ul class="small-learn-icon"> <li> <p> </p><p>Audio</p> <p></p> </li> <li> <p> </p><p>presentations</p> <p></p> </li> <li> <p> </p><p>Role Play</p> <p></p> </li> <li> <p> </p><p>Online</p> <p></p> </li> </ul> </div> </div> </section></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-8 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-cell dnd-column" data-w="12" data-widget-type="cell" data-x="0" style=""> <div class="row-fluid-wrapper row-depth-1 row-number-9 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_widget_1680147860456" style=""> <section class="span12 features-listnew"> <div class="span12 gwcFeatures"> <div class="row-fluid"> <div class="span12 gwcContainer"> <div class="row-fluid"> <div class="span12 sectionHead alignCenter heading"> <p style="font-weight:bold;">Why Study Your Certificate IV in Leadership and Management at Greenwich College?</p> </div> </div> <div class="row-fluid sectioncol"> <div class="span4 featureContentWrap2"> <div class="row-fluid"> <div class="span12 frnt2" style=''''background-image: url("https://www.greenwichcollege.edu.au/hs-fs/hubfs/iStock-1186727950.jpg?width=724&amp;height=483&amp;name=iStock-1186727950.jpg");''''> <div class="row-fluid"> <div class="span12 frntImg"> </div> </div> <div class="row-fluid"> <div class="span12 frontCopy"> <p style="font-weight:bold;">Learn from</p> <p style="font-weight:bold;">industry experts</p> <p> <a class="cta_button pinkCTAsmall" href="https://www.greenwichcollege.edu.au/management-courses/certificate-4-iv-leadership-management?__hstc=122107220.53440f58d7e47852acc26b0b32fa98f4.1782479250262.1782479250262.1782479250262.1&amp;__hssc=122107220.9.1782479250262&amp;__hsfp=1921dd05a39ef67f80eb4e0098c0787f&amp;hsutk=53440f58d7e47852acc26b0b32fa98f4&amp;contentType=standard-page"> Read More </a> </p> </div> </div> </div> </div> <div class="row-fluid"> <div class="span12 bck2"> <div class="row-fluid"> <div class="span12 sectionCopy hover_section_part"> <div class="alignCenter"> <span class="hover-icon"></span> </div> <ul> <li>Highly qualified trainers with comprehensive industry experience and ongoing professional development – to effectively equip you for a successful career in Business.</li> </ul> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1680147860456_" style=""></span> </div> </div> </div> </div> </div> <div class="span4 featureContentWrap2"> <div class="row-fluid"> <div class="span12 frnt2" style=''''background-image: url("https://www.greenwichcollege.edu.au/hs-fs/hubfs/iStock-1695161338.jpg?width=724&amp;height=483&amp;name=iStock-1695161338.jpg");''''> <div class="row-fluid"> <div class="span12 frntImg"> </div> </div> <div class="row-fluid"> <div class="span12 frontCopy"> <p style="font-weight:bold;">Using case studies to improve education</p> <p> <a class="cta_button pinkCTAsmall" href="https://www.greenwichcollege.edu.au/management-courses/certificate-4-iv-leadership-management?__hstc=122107220.53440f58d7e47852acc26b0b32fa98f4.1782479250262.1782479250262.1782479250262.1&amp;__hssc=122107220.9.1782479250262&amp;__hsfp=1921dd05a39ef67f80eb4e0098c0787f&amp;hsutk=53440f58d7e47852acc26b0b32fa98f4&amp;contentType=standard-page"> Read More </a> </p> </div> </div> </div> </div> <div class="row-fluid"> <div class="span12 bck2"> <div class="row-fluid"> <div class="span12 sectionCopy hover_section_part"> <div class="alignCenter"> <span class="hover-icon"></span> </div> <p>Greenwich Management College’s Certificate IV in Leadership &amp; Management features extensive use of real-life case studies to support learning, delivering valuable insights and applications to Australian business.</p> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1680147860456_" style=""></span> </div> </div> </div> </div> </div> <div class="span4 featureContentWrap2"> <div class="row-fluid"> <div class="span12 frnt2" style=''''background-image: url("https://www.greenwichcollege.edu.au/hs-fs/hubfs/iStock-2165450255.jpg?width=1254&amp;height=836&amp;name=iStock-2165450255.jpg");''''> <div class="row-fluid"> <div class="span12 frntImg"> </div> </div> <div class="row-fluid"> <div class="span12 frontCopy"> <p style="font-weight:bold;">Engaging and participatory classes</p> <p> <a class="cta_button pinkCTAsmall" href="https://www.greenwichcollege.edu.au/management-courses/certificate-4-iv-leadership-management?__hstc=122107220.53440f58d7e47852acc26b0b32fa98f4.1782479250262.1782479250262.1782479250262.1&amp;__hssc=122107220.9.1782479250262&amp;__hsfp=1921dd05a39ef67f80eb4e0098c0787f&amp;hsutk=53440f58d7e47852acc26b0b32fa98f4&amp;contentType=standard-page"> Read More </a> </p> </div> </div> </div> </div> <div class="row-fluid"> <div class="span12 bck2"> <div class="row-fluid"> <div class="span12 sectionCopy hover_section_part"> <div class="alignCenter"> <span class="hover-icon"></span> </div> <ul> <li>Classes are engaging and interactive, incorporating practical activities and providing students with opportunities to share ideas, critically assess their thinking, and explore various perspectives on issues.</li> </ul> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1680147860456_" style=""></span> </div> </div> </div> </div> </div> <div class="span4 featureContentWrap2"> <div class="row-fluid"> <div class="span12 frnt2" style=''''background-image: url("https://www.greenwichcollege.edu.au/hs-fs/hubfs/05Hold_Images_New_Site/Courses/WhyGreenwichIMages/MoreOptionsFurtherStudy_360x430.jpg?width=360&amp;height=430&amp;name=MoreOptionsFurtherStudy_360x430.jpg");''''> <div class="row-fluid"> <div class="span12 frntImg"> </div> </div> <div class="row-fluid"> <div class="span12 frontCopy"> <p style="font-weight:bold;">More options for further study</p> <p> <a class="cta_button pinkCTAsmall" href="https://www.greenwichcollege.edu.au/management-courses/certificate-4-iv-leadership-management?__hstc=122107220.53440f58d7e47852acc26b0b32fa98f4.1782479250262.1782479250262.1782479250262.1&amp;__hssc=122107220.9.1782479250262&amp;__hsfp=1921dd05a39ef67f80eb4e0098c0787f&amp;hsutk=53440f58d7e47852acc26b0b32fa98f4&amp;contentType=standard-page"> Read More </a> </p> </div> </div> </div> </div> <div class="row-fluid"> <div class="span12 bck2"> <div class="row-fluid"> <div class="span12 sectionCopy hover_section_part"> <div class="alignCenter"> <span class="hover-icon"></span> </div> <ul> <li>Obtain direct admission to prestigious Australian universities and colleges and earn credits applicable to related academic programs, all without the necessity of completing an entrance examination.</li> </ul> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1680147860456_" style=""></span> </div> </div> </div> </div> </div> <div class="span4 featureContentWrap2"> <div class="row-fluid"> <div class="span12 frnt2" style=''''background-image: url("https://www.greenwichcollege.edu.au/hs-fs/hubfs/05Hold_Images_New_Site/Courses/WhyGreenwichIMages/MoreFlexibility_360x430.jpg?width=360&amp;height=430&amp;name=MoreFlexibility_360x430.jpg");''''> <div class="row-fluid"> <div class="span12 frntImg"> </div> </div> <div class="row-fluid"> <div class="span12 frontCopy"> <p style="font-weight:bold;">Adaptable scheduling choices</p> <p> <a class="cta_button pinkCTAsmall" href="https://www.greenwichcollege.edu.au/management-courses/certificate-4-iv-leadership-management?__hstc=122107220.53440f58d7e47852acc26b0b32fa98f4.1782479250262.1782479250262.1782479250262.1&amp;__hssc=122107220.9.1782479250262&amp;__hsfp=1921dd05a39ef67f80eb4e0098c0787f&amp;hsutk=53440f58d7e47852acc26b0b32fa98f4&amp;contentType=standard-page"> Read More </a> </p> </div> </div> </div> </div> <div class="row-fluid"> <div class="span12 bck2"> <div class="row-fluid"> <div class="span12 sectionCopy hover_section_part"> <div class="alignCenter"> <span class="hover-icon"></span> </div> <ul> <li>Select from evening or weekend classes, allowing you to balance work commitments while immersing yourself in the rich cultural and educational experiences Australia has to offer.</li> </ul> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1680147860456_" style=""></span> </div> </div> </div> </div> </div> <div class="span4 featureContentWrap2"> <div class="row-fluid"> <div class="span12 frnt2" style=''''background-image: url("https://www.greenwichcollege.edu.au/hs-fs/hubfs/iStock-2151853381.jpg?width=1254&amp;height=836&amp;name=iStock-2151853381.jpg");''''> <div class="row-fluid"> <div class="span12 frntImg"> </div> </div> <div class="row-fluid"> <div class="span12 frontCopy"> <p style="font-weight:bold;">Complimentary educational assistance</p> <p> <a class="cta_button pinkCTAsmall" href="https://www.greenwichcollege.edu.au/management-courses/certificate-4-iv-leadership-management?__hstc=122107220.53440f58d7e47852acc26b0b32fa98f4.1782479250262.1782479250262.1782479250262.1&amp;__hssc=122107220.9.1782479250262&amp;__hsfp=1921dd05a39ef67f80eb4e0098c0787f&amp;hsutk=53440f58d7e47852acc26b0b32fa98f4&amp;contentType=standard-page"> Read More </a> </p> </div> </div> </div> </div> <div class="row-fluid"> <div class="span12 bck2"> <div class="row-fluid"> <div class="span12 sectionCopy hover_section_part"> <div class="alignCenter"> <span class="hover-icon"></span> </div> <p>Access to an additional 10 hours of FREE optional learning support per week, for those who need it.</p> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1680147860456_" style=""></span> </div> </div> </div> </div> </div> </div> </div> </div> </div> </section></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-10 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-cell dnd-column" data-w="12" data-widget-type="cell" data-x="0" style=""> <div class="row-fluid-wrapper row-depth-1 row-number-11 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_widget_1680755627766" style=""> <section class="span12 need-to-know sectionPadding needtoknow"> <div class="span12 need-to-know gwcContainer"> <div class="row-fluid"> <div class="span12 widget-span widget-type-header sectionHead"> <p style="font-weight:bold;">Here''''s what you need to know</p> <p> </p> </div> </div> <div class="row-fluid"> <div class="span12 need-to-know"> <div class="row-fluid"> <div class="span4 need-to-know gwcNeedtoKnowThumb entryReq"> <div class="row-fluid"> <div class="span12 widget-span"> <div class="span4img3"> </div> </div> </div> <div class=""> <div class="row-fluid"> <div class="span12 needtoknowdiv"> <div class="title"> <p><strong>Course Commencement</strong><br/>There are 6 intakes per year.</p> </div> <script>$(''''#displayContent1'''').click(function() { $(''''.moreContent1'''').slideToggle(); }); </script> </div> </div> </div> </div> <div class="span4 need-to-know gwcNeedtoKnowThumb entryReq"> <div class="row-fluid"> <div class="span12 widget-span"> <div class="span4img3"> </div> </div> </div> <div class=""> <div class="row-fluid"> <div class="span12 needtoknowdiv"> <div class="title"> <p><strong>Course Duration</strong><br/>Courses are 40-44 weeks<br/>at 20 hours per week.a</p> </div> <script>$(''''#displayContent2'''').click(function() { $(''''.moreContent2'''').slideToggle(); }); </script> </div> </div> </div> </div> <div class="span4 need-to-know gwcNeedtoKnowThumb entryReq"> <div class="row-fluid"> <div class="span12 widget-span"> <div class="span4img3"> </div> </div> </div> <div class=""> <div class="row-fluid"> <div class="span12 needtoknowdiv"> <div class="title"> <p><strong>Entry Requirements</strong><br/>Display entry requirements</p> <i aria-hidden="true" class="fa fa-angle-down" id="displayContent3"></i> </div> <script>$(''''#displayContent3'''').click(function() { $(''''.moreContent3'''').slideToggle(); }); </script> </div> </div> </div> </div> </div> <div class="row-fluid"> <div class="span12 widget-span entryReq moreContent1" style="display: none;"> </div> </div> <div class="row-fluid"> <div class="span12 widget-span entryReq moreContent2" style="display: none;"> </div> </div> <div class="row-fluid"> <div class="span12 widget-span entryReq moreContent3" style="display: none;"> <p><strong>Entry Requirement</strong></p> <ul> <li>All students must be 18 years or older at the commencement of their course</li> </ul> <p><strong>English Language Requirement</strong></p> <ul> <li>All students must have a minimum English language proficiency of IELTS 5.5 or equivalent<span> </span><strong>OR</strong></li> <li>Have successfully completed one of the following courses with Greenwich English College: General English (Upper Intermediate Level 8 weeks*), English for Business (12 weeks), Cambridge PET * FCE and CAE, EVS, EAP and IELTS* (*With exit point of 5.5 or higher)</li> <li>Direct entry to students on passing Greenwich English College Placement Test (online and on campus testing options)</li> </ul> <p><strong>Academic Requirement</strong></p> <ul> <li>Students must have successfully completed Australian Year 10 or overseas equivalent to Australian Year 10</li> </ul> </div> </div> </div> </div> </div> </section></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div> </div> </div> </main> <div data-global-resource-path="greenwich-theme-2023/templates/partials/footer.html"><div class="footer-section"> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_module_16789435566256" style=""><div class="row-fluid"> <div class="span12"> <div class="row-fluid"> <div class="span12 gwcFooter"> <div class="row-fluid"> <div class="span12 sectionPaddingSmall alignCente