UPDATE courses SET
    course_description = '<html><body><div class="row-fluid"> <div class="span6 content"> <p style="font-weight:bold;"><span style="color: #000000;">What you will learn:</span></p> <p style="line-height: 1.5;"><strong>BSBSTR601</strong> Manage innovation and continuous improvement<br/><strong>BSBPEF502</strong> Develop and use emotional intelligence<br/><strong>BSBPMG633</strong> Provide leadership for the program<br/><strong>BSBPMG634</strong> Facilitate stakeholder engagement (core)<br/><strong>BSBPMG637</strong> Engage in collaborative alliances<br/><strong>BSBTWK503</strong> Manage meetings<br/><strong>BSBLDR601</strong> Lead and manage organisational change<br/><strong>BSBPMG630</strong> Enable program execution (core)<br/><strong>BSBPMG635</strong> Implement program governance (core)<br/><strong>BSBPMG636</strong> Manage benefits (core)<br/><strong>BSBPMG631</strong> Manage program delivery<br/><strong>BSBPMG632</strong> Manage program risk</p> <div class="hs-cta-node"> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1681177863860_" style=""></span> </div> </div> <div class="span6 image"> </div> </div></body></html>',
