UPDATE courses SET
    course_description = '<html><body><div class="row-fluid"> <div class="span6 content"> <p style="font-weight:bold;"><span style="color: #000000;">You will learn to</span></p> <p><strong>BSBCRT611</strong> - Apply critical thinking for complex problem solving (Core)<br/><strong>BSBLDR601</strong> - Lead and manage organisational change (Core)<br/><strong>BSBLDR602</strong> - Provide leadership across the organisation (Core)<br/><strong>BSBOPS601</strong> - Develop and implement business plans (Core)<br/><strong>BSBSTR601</strong> - Manage innovation and continuous improvement (Core)<br/><strong>BSBPEF501</strong> - Manage personal and professional development<br/><strong>BSBPMG633</strong> - Provide leadership for the program<br/><strong>BSBSTR602</strong> - Develop organisational strategies<br/><strong>BSBPMG637</strong> - Engage in collaborative alliance<br/><strong>BSBSUS601</strong> - Lead corporate social responsibility</p> <p><strong>Career Opportunities:</strong><br/>Operations Manager, Business Manager/Owner, Senior Management, Change Implementation Manager, HR Manager, Team Leader/Manager, Executive Manager, Area Manager, Business Development Manager, Departmental Manager and more...</p> <div class="hs-cta-node"> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1681179826274_" style=""></span> </div> </div> <div class="span6 image"> </div> </div></body></html>',
    total_course_duration = '76 weeks',
