UPDATE courses SET
    course_description = '<html><body><div class="row-fluid"> <div class="span6 content"> <p style="font-weight:bold;">Who is this course for?</p> <ul style="line-height: 1;"> <li> <h4><span style="color: #666666; font-family: ''''Trebuchet MS'''', Geneva, Tahoma, sans-serif;"><strong>Anyone looking to further their skills and knowledge</strong> in Information Technology.</span></h4> </li> <li> <h4><span style="color: #666666; font-family: ''''Trebuchet MS'''', Geneva, Tahoma, sans-serif;"><strong>Individuals with relevant IT experience</strong> who aspire to lead and advance in their careers.</span></h4> </li> <li> <h4><span style="color: #666666; font-family: ''''Trebuchet MS'''', Geneva, Tahoma, sans-serif;">Those eager to study a <strong>nationally recognised course</strong> to gain qualifications and enhance their career opportunities in the IT industry.</span></h4> </li> </ul> <p><strong>DURATION: </strong><span></span>12 terms- Each term includes 6 weeks of study plus 2 weeks holidays</p> <p>Choose from Sydney, Melbourne, Gold Coast, or Adelaide</p> <p> </p> <span></span> <p> </p> <div class="hs-cta-node"> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_cta" data-hs-cos-general-type="widget" data-hs-cos-type="cta" id="hs_cos_wrapper_widget_1703222601353_" style=""></span> </div> </div> <div class="span6 image"> </div> </div></body></html>',
