title="Download Your Course Guide"><p>Download Your</p> <p>Course Guide</p></a></span><script charset="utf-8" src="/hs/cta/cta/current.js"></script><script type="text/javascript"> hbspt.cta._relativeUrls=true;hbspt.cta.load(493380, ''''ccb12321-aa43-4c0a-b47c-d4a726e1a946'''', {"useNewLoader":"true","region":"na1"}); </script></span><!-- end HubSpot Call-to-Action Code --></span> </div> </div> </div> <div class="modal-footer"> <button class="close">X</button> </div> </div> </div> </div></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-2 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-cell dnd-column" data-w="12" data-widget-type="cell" data-x="0" style=""> <div class="row-fluid-wrapper row-depth-1 row-number-3 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_widget_1738026808571" style=""> <section class="heading-content" id="whyGreenwich"> <div class="container"> <div class="row"> <p style="font-weight:bold;">Master Advanced IT Skills</p> <p><span>The 104-week ICT60220 Advanced Diploma of Information Technology equips students with advanced skills in networking, IT support, web development, programming, and more. It prepares graduates for roles like IT managers and technical consultants by covering topics such as network security, cloud computing, and IT project management. The course emphasizes practical learning for senior IT roles, focusing on complex tasks and strategic business solutions across various industries.</span><span></span></p> </div> </div> </section></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-4 dnd-section"> <div class="row-fluid"> <div class="span12 widget-span widget-type-cell dnd-column" data-w="12" data-widget-type="cell" data-x="0" style=""> <div class="row-fluid-wrapper row-depth-1 row-number-5 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_widget_1738638620681" style=""> <section class="span12 fourcol-resources"> <div class="row-fluid"> <div class="span12 container-width"> <div class="row-fluid wrap"> </div> </div> </div> </section></div> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> </div><!--end widget-span --> </div><!--end row--> </div><!--end row-wrapper --> <div class="row-fluid-wrapper row-depth-1 row-number-6 dnd-section dnd_area-row-3-vertical-alignment"> <div class="row-fluid"> <div class="span4 widget-span widget-type-cell cell_173803113233010-vertical-alignment dnd-column" data-w="4" data-widget-type="cell" data-x="0" style=""> <div class="row-fluid-wrapper row-depth-1 row-number-7 dnd-row"> <div class="row-fluid"> <div class="span12 widget-span widget-type-custom_widget module_1738031132331-flexbox-positioning module_1738031132331-hidden dnd-module" data-w="12" data-widget-type="custom_widget" data-x="0" style=""> <div class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module widget-type-linked_image" data-hs-cos-general-type="widget" data-hs-cos-type="module" id="hs_cos_wrapper_module_1738031132331" style=""> <span class="hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_linked_image" data-hs-cos-general-type="widget" data-hs-cos-type="linked_image" id="hs_cos_wrapper_module_1738031132331_" styl